const message = $json.message ?? $json.edited_message ?? {};
const originalText = String(message.text ?? message.caption ?? "").trim();

// Mask Telegram bot tokens and common API-key patterns.
const redactedText = originalText
  .replace(/\b\d{6,12}:[A-Za-z0-9_-]{20,}\b/g, "[REDACTED_SECRET]")
  .replace(/\bsk-[A-Za-z0-9_-]{16,}\b/g, "[REDACTED_SECRET]")
  .replace(/\bgh[pousr]_[A-Za-z0-9_]{20,}\b/g, "[REDACTED_SECRET]");

// Normalise the /history command (also accepts /history@BotName).
const normalisedText = /^\/history(@\w+)?$/i.test(redactedText) ? "/history" : redactedText;

const receivedAt = message.date
  ? new Date(message.date * 1000).toISOString()
  : new Date().toISOString();

return {
  json: {
    chatId: message.chat?.id != null ? String(message.chat.id) : "",
    messageText: normalisedText,
    receivedAt
  }
};

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0 && (r.verdict || r.control_id || r.practice)).slice(0, 4);
let historyMessage;
if (rows.length === 0) {
  historyMessage = "NGP-030 History: no saved assessments for this chat yet. Send a security practice to create one.";
} else {
  const lines = rows.slice(0, 4).map((r, idx) => {
    const practice = String(r.practice || "(no practice text)").replace(/\s+/g, " ").slice(0, 160);
    return [
      (idx + 1) + ". " + (r.mapped_at_ist || "time n/a") + " IST",
      "Practice: " + practice,
      "Control: " + (r.control_id || "Requires Review") + (r.control_name && r.control_name !== "Requires Review" ? " – " + r.control_name : ""),
      "Verdict: " + (r.verdict || "Requires Review") + " | Severity: " + (r.severity || "Requires Review"),
      "Gap: " + String(r.gap || "Requires Review").slice(0, 200)
    ].join("\n");
  });
  historyMessage = "NGP-030 – Last " + rows.length + " assessment(s):\n\n" + lines.join("\n\n");
}
return [{ json: { historyMessage: historyMessage.slice(0, 4000) } }];

const queryText =
  typeof query === "string"
    ? query
    : query && typeof query === "object"
      ? String(query.query ?? query.text ?? "")
      : String(query ?? "");

const q = queryText.toLowerCase().trim();

const controls = [
  {
    id: "IA-5",
    name: "Authenticator Management",
    keywords: [
      "password",
      "passwords",
      "rotation",
      "rotate",
      "rotating",
      "credential",
      "credentials",
      "authenticator",
      "password change",
      "password policy",
      "reset password"
    ]
  },
  {
    id: "AC-2",
    name: "Account Management",
    keywords: [
      "account",
      "admin account",
      "user account",
      "account review",
      "disable account",
      "account creation",
      "account removal"
    ]
  },
  {
    id: "AC-6",
    name: "Least Privilege",
    keywords: [
      "least privilege",
      "minimum access",
      "privileged access",
      "permissions",
      "restrict access",
      "access rights",
      "unauthorized access"
    ]
  },
  {
    id: "AU-2",
    name: "Event Logging",
    keywords: [
      "logging",
      "logs",
      "audit events",
      "record events",
      "monitor events",
      "security logs",
      "event monitoring"
    ]
  },
  {
    id: "IA-2",
    name: "Identification and Authentication (Organizational Users)",
    keywords: [
      "mfa",
      "multi-factor",
      "multifactor",
      "two-factor",
      "authentication",
      "login verification",
      "identity verification"
    ]
  },
  {
    id: "CM-6",
    name: "Configuration Settings",
    keywords: [
      "configuration",
      "security settings",
      "secure configuration",
      "baseline",
      "system hardening",
      "configuration changes"
    ]
  }
];

if (!q) {
  return JSON.stringify({
    lookup_method: "keyword matching",
    query: "",
    candidate_controls: [],
    note: "No security practice was provided."
  });
}

const matches = controls
  .map(control => {
    const matchedKeywords = control.keywords.filter(keyword =>
      q.includes(keyword)
    );

    return {
      id: control.id,
      name: control.name,
      score: matchedKeywords.length,
      matched_keywords: matchedKeywords
    };
  })
  .filter(control => control.score > 0)
  .sort((a, b) => b.score - a.score);

if (matches.length === 0) {
  return JSON.stringify({
    lookup_method: "keyword matching",
    query: queryText,
    candidate_controls: [],
    note: "No clear keyword match found. Review the official NIST SP 800-53 catalog."
  });
}

return JSON.stringify({
  lookup_method: "keyword matching",
  query: queryText,
  candidate_controls: matches.slice(0, 3).map(control => ({
    id: control.id,
    name: control.name,
    keyword_matches: control.score,
    matched_keywords: control.matched_keywords
  })),
  note: "These are candidate controls only. Keyword matching does not verify official control wording or prove compliance. Verify the applicable NIST control and supporting evidence before assigning a verdict."
});

const src = $('Code in JavaScript').first().json;
const raw = typeof $json.output === "string" ? $json.output : "";
// Normalise unicode hyphens/dashes and non-breaking spaces produced by the model.
const text = raw.replace(/[\u2010\u2011\u2012]/g, "-").replace(/\u00a0/g, " ").trim();
const RR = "Requires Review";

function field(label, next) {
  const re = new RegExp(label + ":\\s*([\\s\\S]*?)(?=\\n\\s*(?:" + next + "):|$)", "i");
  const m = text.match(re);
  return m ? m[1].replace(/\s+/g, " ").trim() : "";
}
const LABELS = "Verdict|NIST Control|Reason|Gap|Recommendation";

const verdictRaw = field("Verdict", LABELS).toUpperCase();
const VERDICTS = ["INSUFFICIENT EVIDENCE", "NON-COMPLIANT", "PARTIAL", "COMPLIANT"];
const verdict = VERDICTS.find(v => verdictRaw.startsWith(v)) || RR;

const controlLine = field("NIST Control", LABELS);
const cm = controlLine.match(/\b([A-Z]{2})\s*-\s*(\d{1,2}(?:\s*\(\d+\))?)/);
const controlId = cm ? (cm[1] + "-" + cm[2].replace(/\s+/g, "")) : RR;
let controlName = RR;
if (cm) {
  const rest = controlLine.slice(controlLine.indexOf(cm[0]) + cm[0].length).replace(/^[\s\-\u2013\u2014:]+/, "").trim();
  if (rest) controlName = rest;
}

const reason = field("Reason", LABELS) || RR;
const gap = field("Gap", LABELS) || RR;
const improvement = field("Recommendation", LABELS) || RR;

// Documented severity mapping.
const SEVERITY = { "NON-COMPLIANT": "HIGH", "PARTIAL": "MEDIUM", "INSUFFICIENT EVIDENCE": "MEDIUM", "COMPLIANT": "LOW" };
const severity = SEVERITY[verdict] || RR;

const mappedAtIst = $now.setZone("Asia/Kolkata").toFormat("yyyy-LL-dd HH:mm:ss");
const executionId = String($execution.id);

const assessmentMessage = text
  ? [
      "Verdict: " + verdict,
      "NIST Control: " + (controlId === RR ? RR : controlId + " – " + controlName),
      "Reason: " + reason,
      "Gap: " + gap,
      "Recommendation: " + improvement,
      "",
      "Severity: " + severity + " | Ref: NGP-030 #" + executionId
    ].join("\n")
  : "NGP-030: The AI assessment returned no text for your message. The request has been logged as 'Requires Review'. Please try again.";

const recordLine = ["NGP-030", "exec #" + executionId, mappedAtIst + " IST", controlId, verdict, severity, gap.slice(0, 120)].join(" | ");

return [{
  json: {
    task_tag: "NGP-030",
    chat_ref: String(src.chatId ?? ""),
    practice: src.messageText ?? "",
    control_id: controlId,
    control_name: controlName,
    verdict,
    severity,
    gap,
    summary: text ? reason : RR,
    execution_id: executionId,
    mapped_at_ist: mappedAtIst,
    improvement,
    record_line: recordLine,
    assessmentMessage
  }
}];
